<script setup lang="ts">import {onMounted,ref,computed} from 'vue';import {supabase} from '@/lib/supabase'
const from=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10)),sales=ref<any[]>([]),expenses=ref<any[]>([]),loading=ref(false),error=ref('')
const revenue=computed(()=>sales.value.reduce((s,x)=>s+Number(x.grand_total||x.total||0),0)),profit=computed(()=>sales.value.some(x=>x.profit===null)?null:sales.value.reduce((s,x)=>s+Number(x.profit||0),0)),expenseTotal=computed(()=>expenses.value.reduce((s,x)=>s+Number(x.amount||0),0))
async function load(){loading.value=true;error.value='';const [s,e]=await Promise.all([supabase.from('sales_reporting').select('id,receipt_no,total,grand_total,profit,payment_method,created_at').gte('created_at',from.value+'T00:00:00').lte('created_at',to.value+'T23:59:59').order('created_at',{ascending:false}),supabase.from('expenses').select('amount,date,category').gte('date',from.value).lte('date',to.value)]);if(s.error||e.error)error.value=s.error?.message??e.error?.message??'';sales.value=s.data??[];expenses.value=e.data??[];loading.value=false}onMounted(load)
</script><template><section class="page-wrap"><div class="page-heading"><div><h1>Reports</h1><p>Sales, gross profit and expenses for a selected period.</p></div><button class="btn" @click="load">Refresh report</button></div><div class="toolbar"><label>From <input v-model="from" type="date" class="control"></label><label>To <input v-model="to" type="date" class="control"></label></div><p v-if="error" class="alert">{{error}}</p><p v-if="loading" class="empty">Loading report…</p><template v-else><div class="stats-grid"><article class="stat"><span>Transactions</span><strong>{{sales.length}}</strong></article><article class="stat"><span>Revenue</span><strong>UGX {{revenue.toLocaleString()}}</strong></article><article class="stat"><span>Gross profit</span><strong>{{profit===null?'Restricted':'UGX '+profit.toLocaleString()}}</strong></article><article class="stat"><span>Expenses</span><strong>UGX {{expenseTotal.toLocaleString()}}</strong></article><article class="stat"><span>Net after expenses</span><strong>{{profit===null?'Restricted':'UGX '+(profit-expenseTotal).toLocaleString()}}</strong></article></div><div class="panel mt"><h2>Sales detail</h2><div class="table-scroll"><table><thead><tr><th>Receipt</th><th>Date</th><th>Payment</th><th>Revenue</th><th>Gross profit</th></tr></thead><tbody><tr v-for="s in sales" :key="s.id"><td>{{s.receipt_no??s.id}}</td><td>{{new Date(s.created_at).toLocaleString()}}</td><td>{{s.payment_method}}</td><td>UGX {{Number(s.grand_total||s.total).toLocaleString()}}</td><td>{{s.profit===null?'Restricted':'UGX '+Number(s.profit).toLocaleString()}}</td></tr></tbody></table></div></div></template></section></template>
